task frequency_Of_Largest(n: int, s: seq) returns (r: int)
  requires n >= 0
  requires len(s) == n
  ensures r == 0 ==> n == 0
  ensures r > 0 ==> r >= 1
  ensures r == 0 ==> n == 0
  ensures r > 0 ==> r == len([x in s | x == max(s)])
{
  if n == 0 {
    r := 0;
  } else {
    var max_val: int := s[0];
    var count: int := 1;
    var i: int := 1;
    while i < n
      invariant 1 <= i and i <= n
      invariant max_val == max(s[0..i])
      invariant count == len([x in s[0..i] | x == max_val])
      decreases n - i
    {
      if s[i] > max_val {
        max_val := s[i];
        count := 1;
      } else {
        if s[i] == max_val {
          count := count + 1;
        }
      }
      i := i + 1;
    }
    r := count;
  }
}
